#include <Snooker/AI/ShotCandidate.h>
#include <Snooker/Service/ISnookerPhysicsService.h>
#include <fstream>
#include <iterator>
#include <iostream>
#define CHECK(x) do{if(!(x)){std::cerr<<"FAIL AI candidate "<<__LINE__<<": "<<#x<<"; "<<error<<'\n';return 1;}}while(false)
std::string Read(const char*p){std::ifstream f(p);return {std::istreambuf_iterator<char>(f),{}};}
int main(int argc,char**argv){using namespace Snooker;std::string error;CHECK(argc==2);PhysicsBundle bundle;CHECK(PhysicsBundle::Deserialize(Read(argv[1]),bundle,&error));TableGeometry geometry;CHECK(GenerateTableGeometry(bundle.Table,bundle.Cushions,bundle.Pockets,bundle.Geometry,geometry,&error));BallState cue;cue.Id=1;cue.PositionMeters={0,0,cue.RadiusMeters};auto red=cue;red.Id=2;red.PositionMeters={1.5,-.75,red.RadiusMeters};PhysicsClock clock;auto physics=PhysicsSnapshot::Capture(clock,{cue,red},bundle.Version,ESnapshotPhase::BeforeShot);BallDefinition c;c.Id=1;c.Type=EBallType::Cue;c.InitialPositionMeters=cue.PositionMeters;auto r=c;r.Id=2;r.Type=EBallType::Red;r.InitialPositionMeters=red.PositionMeters;MatchState match;auto query=CreateAIStateQuery(match,physics,{c,r},bundle.Cue,&error);CHECK(query);ShotCandidate candidate;CHECK(CreatePotCandidate(*query,geometry,2,3,.5,candidate,&error));CHECK(candidate.TargetBall==2&&candidate.Pocket==3&&candidate.Risk>0&&candidate.CutAngleRadians<Pi/2);ShotInput input;CHECK(candidate.ToShotInput(*query,input,&error));CHECK(input.CueBallId==1&&input.CueProfileId==bundle.Cue.Id&&input.ValidateFor(bundle.Cue,cue,&error));const auto hash=query->StateHash();CHECK(!CreatePotCandidate(*query,geometry,1,3,.5,candidate,&error));CHECK(!CreatePotCandidate(*query,geometry,2,999,.5,candidate,&error));CHECK(!CreatePotCandidate(*query,geometry,2,3,-1,candidate,&error));CHECK(query->StateHash()==hash);auto bad=candidate;bad.CueDirection={};CHECK(!bad.ToShotInput(*query,input,&error));std::cout<<"PASS ghost-ball candidate, legal target/pocket, player ShotInput conversion and rejection\n";}
